@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@implements IAsyncDisposable
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger

<PageTitle>Shipment @TrackingNumber</PageTitle>

@if (error is not null)
{
    <div class="alert alert-danger">
        <p>@error</p>
        <button class="btn btn-outline-danger" @onclick="LoadAsync">Retry</button>
    </div>
}
else if (shipment is null)
{
    <div class="placeholder-glow">
        <h3>Loading shipment <strong>@TrackingNumber</strong>…</h3>
        <p class="placeholder col-6"></p>
        <p class="placeholder col-4"></p>
    </div>
}
else
{
    @if (isLoading)
    {
        <p><em>Refreshing…</em></p>
    }
    <h3>Shipment @shipment.TrackingNumber</h3>
    <dl class="row">
        <dt class="col-sm-3">Status</dt>
        <dd class="col-sm-9">@shipment.Status</dd>

        <dt class="col-sm-3">Location</dt>
        <dd class="col-sm-9">@shipment.Location</dd>

        <dt class="col-sm-3">Estimated Delivery</dt>
        <dd class="col-sm-9">@shipment.EstimatedDelivery.ToString("f")</dd>
    </dl>

    <h4>Tracking History</h4>
    <ul class="list-group">
        @foreach (var update in shipment.Updates.OrderByDescending(u => u.Timestamp))
        {
            <li class="list-group-item">
                <strong>@update.Timestamp.ToString("g")</strong> — @update.Description
            </li>
        }
    </ul>
}

@code {
    [Parameter] public string TrackingNumber { get; set; } = default!;

    private CancellationTokenSource? cts;
    private string? loadedTrackingNumber;
    private ShipmentDetails? shipment;
    private bool isLoading;
    private string? error;

    protected override async Task OnParametersSetAsync()
    {
        if (string.Equals(TrackingNumber, loadedTrackingNumber, StringComparison.OrdinalIgnoreCase))
        {
            return;
        }

        loadedTrackingNumber = TrackingNumber;
        await LoadAsync();
    }

    private async Task LoadAsync()
    {
        if (cts is not null)
        {
            await cts.CancelAsync();
            cts.Dispose();
        }

        cts = new CancellationTokenSource();
        var cancellationToken = cts.Token;

        error = null;
        isLoading = true;

        try
        {
            var result = await ShipmentService.GetShipmentAsync(TrackingNumber, cancellationToken);
            shipment = result;
        }
        catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
        {
            // Self-cancellation (parameter change or dispose) — let ComponentBase handle it.
            throw;
        }
        catch (OperationCanceledException ex)
        {
            Logger.LogWarning(ex, "Request timed out for shipment {TrackingNumber}", TrackingNumber);
            error = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Failed to load shipment {TrackingNumber}", TrackingNumber);
            error = "Unable to load shipment details. Please try again.";
        }
        finally
        {
            isLoading = false;
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (cts is not null)
        {
            await cts.CancelAsync();
            cts.Dispose();
        }
    }
}

